 "content": "def transform(grid):
    # Recolor 8-neighbor exterior around outline, fill enclosed holes while retaining center pixel.
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    ones={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    # connected components, 8-neighbor
    comps=[]
    while ones:
        seed=ones.pop(); comp={seed}; q=[seed]
        while q:
            r,c=q.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    p=(r+dr,c+dc)
                    if p in ones: ones.remove(p);comp.add(p);q.append(p)
        comps.append(comp)
    for comp in comps:
        rs=[r for r,c in comp];cs=[c for r,c in comp]
        top,bottom,left,right=min(rs),max(rs),min(cs),max(cs)
        zeros={(r,c) for r in range(top,bottom+1) for c in range(left,right+1) if grid[r][c]==0}
        # interior zeros are enclosed under 4-connectivity; preserve one central cell
        exterior=set();q=[]
        for p in zeros:
            r,c=p
            if r in (top,bottom) or c in (left,right): exterior.add(p);q.append(p)
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in zeros and p not in exterior:exterior.add(p);q.append(p)
        interior=zeros-exterior
        if interior:
            center=((top+bottom)//2,(left+right)//2)
            for p in interior:
                out[p[0]][p[1]]=0 if p==center else 3
        for r,c in comp:
