 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]);out=[r[:] for r in grid]
    # Identify separate 1-objects with 4-connectivity.
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    comps=[]
    while unseen:
        seed=unseen.pop(); comp={seed}; q=[seed]
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen: unseen.remove(p);comp.add(p);q.append(p)
        comps.append(comp)
    for comp in comps:
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        top,bottom,left,right=min(rs),max(rs),min(cs),max(cs)
        # Fill all zero regions inside the bounding rectangle with 3, except a single 0 marker.
        zeros={(r,c) for r in range(top,bottom+1) for c in range(left,right+1) if grid[r][c]==0}
        boundary=set(); q=[]
        for p in zeros:
            r,c=p
            if r in (top,bottom) or c in (left,right): boundary.add(p); q.append(p)
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in zeros and p not in boundary: boundary.add(p);q.append(p)
        enclosed=zeros-boundary
        if enclosed:
            # preserve the central zero when present; color every other enclosed cell
            center=((top+bottom)//2,(left+right)//2)
            for r,c in enclosed:
                if (r,c)!=center: out[r][c]=3
        # Color a one-cell exterior halo around the object's bounding box, but retain board edge.
        for r in range(max(0,top-1),min(h,bottom+2)):
            for c in range(max(0,left-1),min(w,right+2)):
                if grid[r][c]==0 and (r<top or r>bottom or c<left or c>right):out[r][c]=2
    return out
